function ItemList({ items, onDelete }) {
  return items.map((item) => (
    <li key={item.id}>
      {item.name}
      <button onClick={() => onDelete(item.id)}>Delete</button>
    </li>
  ));
}

function SearchBox() {
  function handleChange(event) {
    console.log(event.target.value);
  }

  function handleKeyDown(event) {
    if (event.key === "Escape") {
      event.target.blur();
    }
  }

  return <input onChange={handleChange} onKeyDown={handleKeyDown} />;
}

function LoginForm({ onSubmit }) {
  function handleSubmit(event) {
    event.preventDefault();  // stop the page reloading
    onSubmit();
  }

  return (
    <form onSubmit={handleSubmit}>
      <button type="submit">Sign in</button>
    </form>
  );
}

function Inbox({ unreadCount }) {
  return (
    <div>
      <h2>Inbox</h2>
      {unreadCount > 0 && <p>{unreadCount} unread messages</p>}
    </div>
  );
}

function UserProfile({ user, isLoading, error }) {
  if (isLoading) return <Spinner />;
  if (error) return <ErrorMessage error={error} />;
  if (!user) return null;

  return (
    <section>
      <h2>{user.name}</h2>
      <p>{user.bio}</p>
    </section>
  );
}

const STATUS_LABELS = {
  pending: <Badge tone="warning">Pending</Badge>,
  shipped: <Badge tone="info">Shipped</Badge>,
  delivered: <Badge tone="success">Delivered</Badge>,
};

function OrderStatus({ status }) {
  return STATUS_LABELS[status] || <Badge>Unknown</Badge>;
}
